    Buffer verts,indices,uniform,vertex_constants,readback,staging,depth_readback,stencil_readback;
    std::array<Buffer,BatchLimit-1> extra_verts{},extra_indices{};
    uint32_t uniform_stride=4096,constant_stride=3072;
