            for(auto& b:extra_verts)Destroy(b);
            for(auto& b:extra_indices)Destroy(b);
            Destroy(uniform);Destroy(vertex_constants);Destroy(readback);Destroy(staging);
            Destroy(depth_readback);Destroy(stencil_readback);
