        for(unsigned i=0;i<4;++i){CreateImage(textures[i],2,2,VK_IMAGE_USAGE_SAMPLED_BIT|VK_IMAGE_USAGE_TRANSFER_DST_BIT);tex_width[i]=tex_height[i]=2;}
