        std::vector<uint32_t> data(static_cast<size_t>(bytes)/4);f.seekg(0);f.read(reinterpret_cast<char*>(data.data()),bytes);
        if(!f||data[0]!=0x07230203)throw std::runtime_error("Bad shader file");
